import pathlib,json,os,subprocess,time,hashlib,sys
R=pathlib.Path(__file__).resolve().parent;T=pathlib.Path('/workspace/shared/lean-runtime-20261009');G=pathlib.Path('/workspace/shared/g5-modular-integration-20261009-1754z');M=T/'mathlib';B=R/'build';E=R/'evidence';B.mkdir(exist_ok=True);E.mkdir(exist_ok=True)
for origin in [T/'baseline181-build',G/'build']:
 for f in origin.rglob('*.olean'):
  q=B/f.relative_to(origin);q.parent.mkdir(parents=True,exist_ok=True)
  if not q.exists():q.symlink_to(f.resolve())
pins=json.loads((R/'SOURCE-PINS.json').read_text());order=[];seen=set()
def visit(n):
 if n in seen or n not in pins:return
 seen.add(n)
 for d in pins[n]['imports']:visit(d)
 if n!='UnifiedLean.Source.SourceCrossCarrierNatural':order.append(n)
visit('G2FaithfulTimedOutput')
(R/'BUILD-ORDER.json').write_text(json.dumps(order,indent=2)+'\n')
paths=[B,T/'baseline181-build',G/'build',M/'.lake/build/lib/lean']+[x/'.lake/build/lib/lean' for x in (M/'.lake/packages').iterdir() if x.is_dir()]
env=dict(os.environ,LEAN_PATH=':'.join(map(str,paths)));results=[]
for n in order:
 p=R/'sources'/(n.replace('.','/')+'.lean');o=B/(n.replace('.','/')+'.olean')
 if o.exists() and not o.is_symlink():continue
 if o.is_symlink():o.unlink()
 o.parent.mkdir(parents=True,exist_ok=True);label=str(time.time_ns())+'-'+n
 cmd=[str(T/'lean-4.33.1-linux/bin/lean'),'--trust=0','-j1','-M4096','-Ddebug.skipKernelTC=false','-o',str(o),str(p)];start=time.time()
 try:q=subprocess.run(cmd,cwd=R/'sources',env=env,capture_output=True,text=True,timeout=180)
 except subprocess.TimeoutExpired as q:
  (E/(label+'.timeout.txt')).write_text(str(q));raise
 (E/(label+'.stdout')).write_text(q.stdout);(E/(label+'.stderr')).write_text(q.stderr)
 rec={'module':n,'source_sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'command':cmd,'exit_code':q.returncode,'seconds':time.time()-start,'stdout':label+'.stdout','stderr':label+'.stderr'}
 (E/(label+'.json')).write_text(json.dumps(rec,indent=2)+'\n');results.append(rec)
 print(json.dumps(rec),flush=True)
 if q.returncode:print(q.stdout,flush=True);raise SystemExit(q.returncode)
(R/'PROVIDER-REPLAY-RECEIPT.json').write_text(json.dumps({'results':results,'status':'ALL_REQUESTED_PROVIDERS_PASS','skip_source_natural':'Exact provider reused from prior G5 build'},indent=2)+'\n')
print('ALL_REQUESTED_PROVIDERS_PASS',flush=True)
